import {isLegacySearchHit,openSearchHit} from './search-navigation.mjs';
import React,{useEffect,useRef,useState} from 'react';
import {Modal} from './preferences.tsx';
import {usePreference} from './state.js';
const types={chapter:'正文',character:'角色',world:'世界',planning:'规划',event:'剧情卡',foreshadow:'伏笔',requirements:'写作要求'};
export function HitText({match}){const {snippet,start,length}=match;return <>{snippet.slice(0,start)}<mark>{snippet.slice(start,start+length)}</mark>{snippet.slice(start+length)}</>;}
export function WorkSearch({call,novelId,novelTitle,busy,close,onOpen}){
 const [query,setQuery]=usePreference(`${novelId}:work-search-query`,''),[kind,setKind]=useState('all'),[inactive,setInactive]=useState(false),[result,setResult]=useState(null),[loading,setLoading]=useState(false),[error,setError]=useState(''),[outdated,setOutdated]=useState(false),generation=useRef(0),input=useRef(null);
 useEffect(()=>{input.current?.focus();return()=>{generation.current++;};},[]);
 const search=async(nextKind=kind,more=false)=>{
  const text=more?result?.query:query.trim();if(!text){setResult(null);setError('请输入搜索词');return;}
  const current=++generation.current;setLoading(true);setError('');setOutdated(false);
  try{const value=await call('writing.search',{novelId,query:text,kinds:nextKind==='all'?Object.keys(types):[nextKind],limit:20,maxChars:16000,includeInactiveRequirements:inactive,...(more?{offset:result.nextOffset,snapshot:result.snapshot}:{})});if(current!==generation.current)return;setResult(more?{...value,items:[...result.items,...value.items]}:value);}
  catch(e){if(current===generation.current){setError(e.message);if(more)setOutdated(true);}}
  finally{if(current===generation.current)setLoading(false);}
 };
 const changeKind=value=>{setKind(value);if(result)search(value);};
 return <Modal title="搜索作品" close={close} className="work-search-modal"><div className="work-search"><p className="muted">{novelTitle} · 已保存内容。草稿、历史版本及待确认建议不进入结果。</p><form className="work-search-form" onSubmit={e=>{e.preventDefault();search();}}><input ref={input} type="search" aria-label="搜索作品关键词" placeholder="搜索人名、设定、情节或原文" value={query} maxLength={160} onKeyDown={e=>{if(e.key==='Enter'&&(e.nativeEvent.isComposing||e.keyCode===229))e.preventDefault();}} onChange={e=>setQuery(e.target.value)}/><button className="primary" disabled={loading||!query.trim()}>搜索</button></form><div className="work-search-filters" role="group" aria-label="搜索类型">{[['all','全部'],...Object.entries(types)].map(([id,label])=><button key={id} disabled={loading} aria-pressed={kind===id} className={kind===id?'selected':''} onClick={()=>changeKind(id)}>{label}{result&&<small>{id==='all'?Object.values(result.counts).reduce((sum,n)=>sum+n,0):result.counts[id]}</small>}</button>)}</div><details className="work-search-options"><summary>搜索范围说明</summary><label><input type="checkbox" checked={inactive} onChange={e=>{setInactive(e.target.checked);generation.current++;setLoading(false);setResult(null);setError('');}}/> 包含停用的写作要求</label><p className="muted">按原文查找，不推断相近含义。正文只查当前已保存版本，角色与世界包含别名及可选字段；归档字段不显示。搜索只读取这一本作品。</p></details>
 {error&&<p className="notice error" role="alert">{error}</p>}{loading&&<p role="status">{result?'正在更新搜索结果…':'正在查找…'}</p>}{result&&<><p className="work-search-summary" aria-live="polite">“{result.query}” · {result.kinds.length===1?types[result.kinds[0]]:'全部'} {result.total} 条{query.trim()!==result.query?' · 输入已修改，请重新搜索':''}</p><div className="work-search-results">{result.items.map(hit=><button className={`work-search-hit hit-${hit.kind}`} key={`${hit.kind}:${hit.id}`} disabled={busy||loading} onClick={()=>openSearchHit(hit,{onOpen,onLegacy:setError})}><div className="work-search-hit-heading"><span className="work-search-kind">{isLegacySearchHit(hit)?'旧版只读摘要':types[hit.kind]}</span><strong>{hit.title||'未命名条目'}</strong><span aria-hidden="true">›</span></div><small>{hit.location||''}{hit.location?' · ':''}{hit.match.label}{hit.planned?' · 计划情境':''}{hit.inactive?' · 未启用':''}{['character','world'].includes(hit.kind)?` · ${hit.id.slice(0,8)}`:''}</small><p><HitText match={hit.match}/></p></button>)}</div>{!result.items.length&&!loading&&<p className="work-search-empty">没有找到匹配内容。可以换一个关键词，或选择“全部”。</p>}{result.hasMore&&<button className="work-search-more" disabled={loading||outdated||query.trim()!==result.query||(result.kinds.length===1?result.kinds[0]:'all')!==kind} onClick={()=>search(kind,true)}>查看更多（已显示 {result.items.length} / {result.total}）</button>}{outdated&&<button disabled={loading} onClick={()=>search()}>重新搜索最新资料</button>}</>}{!result&&!loading&&!error&&<p className="work-search-empty">输入关键词，把章节、卡片和时间线中的相关内容一起找出来。</p>}</div></Modal>;
}
export const searchStyles=`
.cuigengji .work-search-modal{width:min(800px,calc(100vw - 32px))}.cuigengji .work-search{min-width:0}.cuigengji .work-search-form{display:flex;gap:8px}.cuigengji .work-search-form input{flex:1;min-width:0;padding:12px}.cuigengji .work-search-form button{flex:none}.cuigengji .work-search-filters{display:flex;flex-wrap:wrap;gap:6px;padding:14px 0}.cuigengji .work-search-filters button{display:flex;align-items:center;gap:7px;border-radius:16px;padding:6px 10px}.cuigengji .work-search-filters small{opacity:.6}.cuigengji .work-search-options{font-size:12px;color:var(--cg-muted);margin-bottom:16px}.cuigengji .work-search-options label{display:flex;gap:8px;align-items:center}.cuigengji .work-search-summary{font-size:12px;color:var(--cg-muted);overflow-wrap:anywhere}.cuigengji .work-search-results{display:grid;gap:10px}.cuigengji .work-search-hit{display:block;width:100%;text-align:left;min-width:0;border-left:3px solid var(--cg-accent);padding:14px;border-radius:10px;overflow-wrap:anywhere}.cuigengji .work-search-hit-heading{display:flex;gap:8px;align-items:baseline}.cuigengji .work-search-hit-heading strong{flex:1;min-width:0}.cuigengji .work-search-kind{font-size:11px;color:var(--cg-muted);flex:none}.cuigengji .work-search-hit>small{display:block;color:var(--cg-muted);font-size:11px;margin-top:7px}.cuigengji .work-search-hit p{white-space:pre-wrap;margin:8px 0 0;line-height:1.65}.cuigengji .work-search-hit mark{color:inherit;background:color-mix(in srgb,var(--cg-accent) 20%,transparent);border-radius:3px}.cuigengji .hit-character{border-left-color:var(--card-character,#8b5cf6)}.cuigengji .hit-world{border-left-color:var(--card-world,#0d9488)}.cuigengji .hit-foreshadow{border-left-color:#bc9257}.cuigengji .work-search-more{display:block;margin:16px auto}.cuigengji .work-search-empty{padding:24px 0;color:var(--cg-muted)}@media(max-width:600px){.cuigengji .work-search-modal{width:100%;max-width:100%;height:100%;max-height:100%;margin:0;border:0;border-radius:0}.cuigengji .work-search-modal .utility-content{padding:12px}.cuigengji .work-search-hit{padding:12px}.cuigengji .work-search-filters{gap:6px}.cuigengji .work-search-filters button{font-size:12px}}
`;
